const GENKIT_SERVER_URL = process.env.GENKIT_SERVER_URL || 'http://localhost:3101';

export async function runFlow<TInput, TOutput>(flowName: string, data: TInput): Promise<TOutput> {
  try {
    const response = await fetch(`${GENKIT_SERVER_URL}/${flowName}`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ data }),
    });

    if (!response.ok) {
      const errorText = await response.text();
      throw new Error(`Genkit Flow Error (${response.status}): ${errorText}`);
    }

    const result = await response.json();
    return result.result as TOutput;
  } catch (error) {
    console.error(`Failed to run flow '${flowName}':`, error);
    throw error;
  }
}
